<form class="bg-white rounded shadow p-4 mb-4 grid grid-cols-1 md:grid-cols-4 gap-3"><input class="border p-2" name="search" value="<?= $h($_GET['search']??'') ?>" placeholder="N° brouillon, client, téléphone"><select class="border p-2" name="utilisateur_id"><option value="">Tous les utilisateurs</option><?php foreach($users as $user):?><option value="<?= $user['id'] ?>" <?= $user['id']==($_GET['utilisateur_id']??'')?'selected':'' ?>><?= $h($user['nom'].' '.$user['prenom']) ?></option><?php endforeach;?></select><select class="border p-2" name="period"><option value="">Toute période</option><option value="today" <?= ($_GET['period']??'')==='today'?'selected':'' ?>>Brouillons du jour</option><option value="week" <?= ($_GET['period']??'')==='week'?'selected':'' ?>>Cette semaine</option><option value="month" <?= ($_GET['period']??'')==='month'?'selected':'' ?>>Ce mois</option></select><div class="flex gap-2"><input class="border p-2 w-full" type="date" name="from" value="<?= $h($_GET['from']??'') ?>"><input class="border p-2 w-full" type="date" name="to" value="<?= $h($_GET['to']??'') ?>"></div><button class="bg-blue-700 text-white rounded p-2">Filtrer</button><a class="bg-gray-600 text-white rounded p-2 text-center" href="/suivi-client/ouvrir-saisie">Réinitialiser</a></form>
<div class="overflow-x-auto"><table class="w-full bg-white text-sm"><thead class="bg-gray-200"><tr><th class="p-2 text-left">N° brouillon</th><th>Date</th><th>Heure</th><th>Client</th><th>Téléphone</th><th>Montant prévu</th><th>Mode</th><th>Créé par</th><th>Dernière modification</th><th>Statut</th><th>Actions</th></tr></thead><tbody><?php foreach($drafts as $draft):?><tr class="border-t"><td class="p-2"><?= $h($draft['numero_brouillon']) ?></td><td><?= $h(date('d/m/Y',strtotime($draft['date_mouvement']))) ?></td><td><?= $h(date('H:i',strtotime($draft['date_mouvement']))) ?></td><td><?= $h($draft['nom'].' '.$draft['prenom']) ?></td><td><?= $h($draft['telephone']) ?></td><td class="text-right"><?= $fcfa($draft['montant']) ?></td><td><?= $h($draft['mode_paiement']) ?></td><td><?= $h(trim(($draft['utilisateur_nom']??'').' '.($draft['utilisateur_prenom']??''))) ?></td><td><?= $h($draft['updated_at']) ?></td><td><span class="px-2 py-1 rounded bg-yellow-100 text-yellow-800">Brouillon</span></td><td class="whitespace-nowrap"><a class="text-green-700 mr-2" href="/suivi-client/saisie-reglement?brouillon_id=<?= $draft['id'] ?>">▶ Reprendre</a><a class="text-blue-700 mr-2" href="/suivi-client/saisie-reglement?brouillon_id=<?= $draft['id'] ?>">✏ Modifier</a><a class="text-gray-700 mr-2" href="/suivi-client/brouillons/<?= $draft['id'] ?>/consulter">👁 Consulter</a><form class="inline" method="post" action="/suivi-client/brouillons/<?= $draft['id'] ?>/supprimer" onsubmit="return confirm('Supprimer ce brouillon ?')"><button class="text-red-700">🗑 Supprimer</button></form></td></tr><?php endforeach;?><?php if(!$drafts):?><tr><td colspan="11" class="p-6 text-center text-gray-500">Aucun brouillon trouvé.</td></tr><?php endif;?></tbody></table></div></main></body></html>
